const TEXTS = [
  '拔塞过程三个阶段（示意）',
  'u = x / h',
  'u = 0',
  'u = 1/2',
  'u = 1',
  '瓶口基准线',
  'h',
  'x',
  'x',
  '位移按真实比例：u = 1 时木塞底部到达瓶口基准线'
];

const visual = {
  prepare: function (input) {
    return TEXTS.map(function (s) { return { kind: 'text', payload: s }; });
  },
  render: function (input, metrics) {
    var sdk = visualSdk;
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = 24;
    var panelW = (W - 2 * margin) / 3;
    var mouthY = H * 0.46;
    var corkLen = Math.min(H * 0.27, panelW * 0.55);
    var neckBottom = mouthY + corkLen * 1.22;
    var corkHalf = corkLen * 0.17;
    var wall = Math.max(4, corkHalf * 0.3);
    var outer = corkHalf + wall;
    var ink = '#26354a';
    var refInk = '#7b8aa0';
    var glassLight = '#c2cfdd';
    var glassDark = '#9fb0c4';
    var corkEdge = '#8a6a45';
    var corkBody = '#d3b083';

    function line(x1, y1, x2, y2) {
      return sdk.polyline([{ x: x1, y: y1 }, { x: x2, y: y2 }]);
    }
    function rect(x, y, w, h) {
      return sdk.polyline([{ x: x, y: y }, { x: x + w, y: y }, { x: x + w, y: y + h }, { x: x, y: y + h }, { x: x, y: y }]);
    }

    var paths = [];
    var children = [];
    var i;

    function pushPath(pid, cmds, paint, sw) {
      paths.push({ id: pid, commands: cmds });
      children.push({ type: 'path', pathId: pid, fill: paint, stroke: { width: sw } });
    }

    pushPath('ref', line(margin, mouthY, W - margin, mouthY), refInk, 1.4);

    for (i = 0; i < 3; i++) {
      var cxi = margin + panelW * (i + 0.5);
      pushPath('lip' + i, rect(cxi - outer - wall * 1.4, mouthY, (outer + wall * 1.4) * 2, wall * 1.3), glassDark, 1);
      pushPath('lw' + i, rect(cxi - outer - wall, mouthY, wall, neckBottom - mouthY), glassLight, 1);
      pushPath('rw' + i, rect(cxi + outer, mouthY, wall, neckBottom - mouthY), glassLight, 1);
      pushPath('bm' + i, line(cxi - outer - wall, neckBottom, cxi + outer + wall, neckBottom), glassDark, 2);
    }

    for (i = 0; i < 3; i++) {
      var ccx = margin + panelW * (i + 0.5);
      var shift = (i * 0.5) * corkLen;
      var cb = mouthY + corkLen - shift;
      var ct = cb - corkLen;
      pushPath('co' + i, rect(ccx - corkHalf, ct, corkHalf * 2, corkLen), corkEdge, 1);
      pushPath('ci' + i, rect(ccx - corkHalf + 2.4, ct + 2.6, (corkHalf - 2.4) * 2, corkLen - 5.2), corkBody, 1);
    }

    for (i = 0; i < 3; i++) {
      var mcx = margin + panelW * (i + 0.5);
      var ax = mcx - outer - wall - 14;
      if (i === 0) {
        pushPath('mh', line(ax, mouthY, ax, mouthY + corkLen), ink, 1.2);
        pushPath('mh0', line(ax - 4, mouthY, ax + 4, mouthY), ink, 1.2);
        pushPath('mh1', line(ax - 4, mouthY + corkLen, ax + 4, mouthY + corkLen), ink, 1.2);
        children.push({ type: 'label', contentId: 'c6', anchor: { x: ax - 7, y: mouthY + corkLen / 2 }, hAlign: 'right', vAlign: 'middle', color: ink });
      } else {
        var d = (i * 0.5) * corkLen;
        pushPath('ax' + i, sdk.arrow(ax, mouthY, ax, mouthY - d, {}), ink, 1.2);
        pushPath('tk' + i, line(ax - 4, mouthY, ax + 4, mouthY), ink, 1.2);
        children.push({ type: 'label', contentId: i === 1 ? 'c7' : 'c8', anchor: { x: ax - 7, y: mouthY - d / 2 }, hAlign: 'right', vAlign: 'middle', color: ink });
      }
    }

    for (i = 0; i < 3; i++) {
      var lcx = margin + panelW * (i + 0.5);
      children.push({ type: 'label', contentId: 'c' + (2 + i), anchor: { x: lcx, y: neckBottom + 20 }, hAlign: 'center', vAlign: 'top', color: ink });
    }

    children.push({ type: 'label', contentId: 'c5', anchor: { x: W - margin, y: mouthY - 8 }, hAlign: 'right', vAlign: 'bottom', color: refInk });
    children.push({ type: 'label', contentId: 'c0', anchor: { x: W / 2, y: 18 }, hAlign: 'center', vAlign: 'top', color: ink });
    children.push({ type: 'label', contentId: 'c1', anchor: { x: W - margin, y: 18 }, hAlign: 'right', vAlign: 'top', color: ink });
    children.push({ type: 'label', contentId: 'c9', anchor: { x: W / 2, y: H - 8 }, hAlign: 'center', vAlign: 'bottom', color: ink });

    return {
      schemaVersion: 1,
      sceneId: 'cork-pull-stages',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
